12	const DIGEST_HEX = /^[0-9a-f]{64}$/u;
13	const INPUT_KEYS = Object.freeze([
14		"detachedGenesisSignature",
15		"exactCanonicalCommitQcBytes",
16		"exactCanonicalCurrentTrustStateRecordBytes",
17		"exactCanonicalCutValueBytes",
18		"exactCanonicalGenesisAnchorPreimageBytes",
19		"exactCanonicalPredecessorTrustStateRecordBytes",
20		"expectedCurrentHead",
21		"expectedObjectId",
22		"pinnedGenesisAnchorDigest",
23	]);
24	const HEAD_KEYS = Object.freeze(["currentAnchorDigest", "epoch", "objectId"]);
25	const TRUST_KEYS = Object.freeze([
26		"currentAnchorDigest",
27		"currentEpoch",
28		"detachedCurrentAnchorSignature",
29		"exactCanonicalCurrentAnchorPreimageBytes",
30		"exactCanonicalProfileBytes",
31		"exactCanonicalSignerSetBytes",
32		"genesisAnchorDigest",
33		"kind",
34		"objectId",
35		"profileId",
36		"quorum",
37		"version",
38	]);
