40	export type CreatorCheckpointFailureReason =
41		| "commit-qc-rejected"
42		| "current-rejected"
43		| "custody-unavailable"
44		| "expected-head-mismatch"
45		| "genesis-rejected"
46		| "lineage-invalid"
47		| "malformed-input"
48		| "predecessor-rejected";
49	
50	export interface CreatorCheckpointHead {
51		readonly currentAnchorDigest: string;
52		readonly epoch: number;
53		readonly objectId: string;
54	}
55	
56	export interface OpenCreatorCheckpointTrustInput {
57		readonly detachedGenesisSignature: Uint8Array;
58		readonly exactCanonicalCommitQcBytes: Uint8Array;
59		readonly exactCanonicalCurrentTrustStateRecordBytes: Uint8Array;
60		readonly exactCanonicalCutValueBytes: Uint8Array;
61		readonly exactCanonicalGenesisAnchorPreimageBytes: Uint8Array;
62		readonly exactCanonicalPredecessorTrustStateRecordBytes: Uint8Array;
63		readonly expectedCurrentHead: CreatorCheckpointHead;
64		readonly expectedObjectId: string;
65		readonly pinnedGenesisAnchorDigest: string;
66	}
67	
68	export type OpenCreatorCheckpointTrustResult =
69		| Readonly<{ readonly ok: false; readonly reason: CreatorCheckpointFailureReason }>
70		| Readonly<{
71				readonly currentTrust: CurrentAnchorTrust;
72				readonly ok: true;
73				readonly predecessorTrust: CurrentAnchorTrust;
74		  }>;
75	
76	interface TrustRecord extends Readonly<Record<string, unknown>> {
77		readonly currentAnchorDigest: string;
78		readonly currentEpoch: number;
79		readonly detachedCurrentAnchorSignature: Uint8Array;
80		readonly exactCanonicalCurrentAnchorPreimageBytes: Uint8Array;
81		readonly exactCanonicalProfileBytes: Uint8Array;
82		readonly exactCanonicalSignerSetBytes: Uint8Array;
83		readonly genesisAnchorDigest: string;
84		readonly objectId: string;
85	}
86	
87	function failure(reason: CreatorCheckpointFailureReason): OpenCreatorCheckpointTrustResult {
88		return Object.freeze({ ok: false as const, reason });
89	}
90	
91	function plainRecord(value: unknown): value is Readonly<Record<string, unknown>> {
92		if (value === null || typeof value !== "object" || Array.isArray(value)) return false;
93		const prototype = Object.getPrototypeOf(value);
94		return prototype === Object.prototype || prototype === null;
95	}
96	
97	function exactKeys(value: Readonly<Record<string, unknown>>, keys: readonly string[]): boolean {
98		const actual = Reflect.ownKeys(value);
99		return (
100			actual.length === keys.length &&
101			actual.every((key) => typeof key === "string" && keys.includes(key)) &&
102			keys.every((key) => {
103				const descriptor = Object.getOwnPropertyDescriptor(value, key);
104				return descriptor?.enumerable === true && "value" in descriptor;
105			})
106		);
107	}
108	
109	function copiedBytes(value: unknown, maximum = 65_536): Uint8Array | undefined {
110		if (
111			!(value instanceof Uint8Array) ||
112			Object.getPrototypeOf(value) !== Uint8Array.prototype ||
113			value.byteOffset !== 0 ||
114			value.buffer.byteLength !== value.byteLength ||
115			value.byteLength === 0 ||
116			value.byteLength > maximum
117		) {
118			return undefined;
119		}
120		return Uint8Array.from(value);
121	}
122	
123	function exactRecord(bytes: Uint8Array): Readonly<Record<string, unknown>> | undefined {
124		try {
125			const decoded = decodeCanonical(bytes);
126			if (!plainRecord(decoded) || compareBytes(encodeCanonical(decoded), bytes) !== 0) return undefined;
127			return decoded;
128		} catch {
129			return undefined;
130		}
131	}
132	
133	function trustRecord(
134		bytes: Uint8Array,
135		expectedObjectId: string,
136		pinnedGenesisAnchorDigest: string
137	): TrustRecord | undefined {
138		const decoded = exactRecord(bytes);
139		if (
140			decoded === undefined ||
141			!exactKeys(decoded, TRUST_KEYS) ||
142			decoded.kind !== "drp-anchor-trust-state" ||
143			decoded.version !== 1 ||
144			decoded.profileId !== "creator-trusted-v1" ||
145			decoded.quorum !== 1 ||
146			decoded.objectId !== expectedObjectId ||
147			decoded.genesisAnchorDigest !== pinnedGenesisAnchorDigest ||
148			typeof decoded.currentEpoch !== "number" ||
149			!Number.isSafeInteger(decoded.currentEpoch) ||
150			decoded.currentEpoch < 1 ||
151			typeof decoded.currentAnchorDigest !== "string" ||
152			!DIGEST_HEX.test(decoded.currentAnchorDigest) ||
153			!(decoded.detachedCurrentAnchorSignature instanceof Uint8Array) ||
154			decoded.detachedCurrentAnchorSignature.byteLength !== 64 ||
155			!(decoded.exactCanonicalCurrentAnchorPreimageBytes instanceof Uint8Array) ||
156			!(decoded.exactCanonicalProfileBytes instanceof Uint8Array) ||
157			!(decoded.exactCanonicalSignerSetBytes instanceof Uint8Array)
158		) {
159			return undefined;
160		}
161		const anchor = exactRecord(decoded.exactCanonicalCurrentAnchorPreimageBytes);
162		if (
163			anchor?.kind !== "drp-epoch-anchor" ||
164			anchor.objectId !== expectedObjectId ||
165			anchor.epoch !== decoded.currentEpoch ||
166			decoded.currentAnchorDigest !==
167				bytesHex(hashDomain("ts-drp/epoch-anchor/v3", decoded.exactCanonicalCurrentAnchorPreimageBytes))
168		) {
169			return undefined;
170		}
171		return decoded as TrustRecord;
172	}
173	
174	function bytesHex(bytes: Uint8Array): string {
175		let output = "";
176		for (const byte of bytes) output += byte.toString(16).padStart(2, "0");
177		return output;
178	}
179	
180	function validHead(value: unknown): value is CreatorCheckpointHead {
181		return (
182			plainRecord(value) &&
183			exactKeys(value, HEAD_KEYS) &&
184			typeof value.currentAnchorDigest === "string" &&
185			DIGEST_HEX.test(value.currentAnchorDigest) &&
186			typeof value.epoch === "number" &&
187			Number.isSafeInteger(value.epoch) &&
188			value.epoch >= 0 &&
189			typeof value.objectId === "string"
190		);
191	}
