193	/**
194	 * Opens one bounded creator checkpoint from pinned genesis and an immediate predecessor/current pair.
195	 * @param input - Exact genesis, pair, Cut/QC, and independently authenticated current-head carriers.
196	 * @returns Genuine predecessor/current trust capabilities or one frozen fail-closed reason.
197	 */
198	export function openCreatorCheckpointTrust(input: unknown): OpenCreatorCheckpointTrustResult {
199		try {
200			if (!plainRecord(input) || !exactKeys(input, INPUT_KEYS)) return failure("malformed-input");
201			const expectedObjectId = input.expectedObjectId;
202			const pinnedGenesisAnchorDigest = input.pinnedGenesisAnchorDigest;
203			if (
204				typeof expectedObjectId !== "string" ||
205				typeof pinnedGenesisAnchorDigest !== "string" ||
206				!DIGEST_HEX.test(pinnedGenesisAnchorDigest) ||
207				!validHead(input.expectedCurrentHead) ||
208				input.expectedCurrentHead.objectId !== expectedObjectId
209			) {
210				return failure("malformed-input");
211			}
212			const genesisAnchorBytes = copiedBytes(input.exactCanonicalGenesisAnchorPreimageBytes);
213			const genesisSignature = copiedBytes(input.detachedGenesisSignature, 64);
214			const predecessorBytes = copiedBytes(input.exactCanonicalPredecessorTrustStateRecordBytes, 8192);
215			const currentBytes = copiedBytes(input.exactCanonicalCurrentTrustStateRecordBytes, 8192);
216			const cutBytes = copiedBytes(input.exactCanonicalCutValueBytes);
217			const qcBytes = copiedBytes(input.exactCanonicalCommitQcBytes);
218			if (
219				genesisAnchorBytes === undefined ||
220				genesisSignature?.byteLength !== 64 ||
221				predecessorBytes === undefined ||
222				currentBytes === undefined ||
223				cutBytes === undefined ||
224				qcBytes === undefined
225			) {
226				return failure("malformed-input");
227			}
228			const predecessor = trustRecord(predecessorBytes, expectedObjectId, pinnedGenesisAnchorDigest);
229			if (predecessor === undefined) return failure("predecessor-rejected");
230			const current = trustRecord(currentBytes, expectedObjectId, pinnedGenesisAnchorDigest);
231			if (current === undefined) return failure("current-rejected");
232			const genesisRecordBytes = encodeCanonical({
233				currentAnchorDigest: pinnedGenesisAnchorDigest,
234				currentEpoch: 0,
235				detachedCurrentAnchorSignature: genesisSignature,
236				exactCanonicalCurrentAnchorPreimageBytes: genesisAnchorBytes,
237				exactCanonicalProfileBytes: predecessor.exactCanonicalProfileBytes,
238				exactCanonicalSignerSetBytes: predecessor.exactCanonicalSignerSetBytes,
239				genesisAnchorDigest: pinnedGenesisAnchorDigest,
240				kind: "drp-anchor-trust-state",
241				objectId: expectedObjectId,
242				profileId: "creator-trusted-v1",
243				quorum: 1,
244				version: 1,
245			});
246			const genesis = openCurrentAnchorTrust({
247				exactCanonicalTrustStateRecordBytes: genesisRecordBytes,
248				expectedObjectId,
249				pinnedGenesisAnchorDigest,
250			});
251			if (!genesis.ok) return failure("genesis-rejected");
252			const genesisMaterial = resolveCreatorAnchorTrustMaterial(genesis.trust);
253			if (genesisMaterial === undefined) return failure("custody-unavailable");
254			if (
255				!sameBytes(predecessor.exactCanonicalProfileBytes, genesisMaterial.exactCanonicalProfileBytes) ||
256				!sameBytes(predecessor.exactCanonicalSignerSetBytes, genesisMaterial.exactCanonicalSignerSetBytes) ||
257				!ed25519.verify(
258					predecessor.detachedCurrentAnchorSignature,
259					hexBytes(predecessor.currentAnchorDigest),
260					genesisMaterial.publicKey,
261					{ zip215: false }
262				)
263			) {
264				return failure("predecessor-rejected");
265			}
266			if (
267				!sameBytes(current.exactCanonicalProfileBytes, predecessor.exactCanonicalProfileBytes) ||
268				!sameBytes(current.exactCanonicalSignerSetBytes, predecessor.exactCanonicalSignerSetBytes) ||
269				!ed25519.verify(
270					current.detachedCurrentAnchorSignature,
271					hexBytes(current.currentAnchorDigest),
272					genesisMaterial.publicKey,
273					{
274						zip215: false,
275					}
276				)
277			) {
278				return failure("current-rejected");
279			}
280			const currentAnchor = exactRecord(current.exactCanonicalCurrentAnchorPreimageBytes);
281			if (
282				current.currentEpoch !== predecessor.currentEpoch + 1 ||
283				currentAnchor?.previousAnchor !== predecessor.currentAnchorDigest
284			) {
285				return failure("lineage-invalid");
286			}
287			const predecessorTrust = mintCreatorAnchorTrustCheckpointPredecessor(
288				genesis.trust,
289				predecessor.exactCanonicalCurrentAnchorPreimageBytes,
290				predecessor.detachedCurrentAnchorSignature
291			);
292			if (predecessorTrust === undefined) return failure("custody-unavailable");
293			const openedCurrent = openCreatorSuccessorTrust({
294				currentTrust: predecessorTrust,
295				exactCanonicalCommitQcBytes: qcBytes,
296				exactCanonicalCutValueBytes: cutBytes,
297				exactCanonicalTrustStateRecordBytes: currentBytes,
298			});
299			if (!openedCurrent.ok) return failure("commit-qc-rejected");
300			if (
301				input.expectedCurrentHead.currentAnchorDigest !== openedCurrent.trust.currentAnchorDigest ||
302				input.expectedCurrentHead.epoch !== openedCurrent.trust.currentEpoch ||
303				input.expectedCurrentHead.objectId !== openedCurrent.trust.objectId
304			) {
305				return failure("expected-head-mismatch");
306			}
307			return Object.freeze({ currentTrust: openedCurrent.trust, ok: true as const, predecessorTrust });
308		} catch {
309			return failure("malformed-input");
310		}
311	}
312	
313	function sameBytes(left: Uint8Array, right: Uint8Array): boolean {
314		return compareBytes(left, right) === 0;
315	}
316	
317	function hexBytes(value: string): Uint8Array {
318		return Uint8Array.from(value.match(/../gu) ?? [], (part) => Number.parseInt(part, 16));
319	}

1	import { decodeCanonical } from "@ts-drp/canonical";
