3	import {
4		assertDurableIssueScope,
5		copyDurableIssueScope,
6		DurableIssuanceInvalidArgumentError,
7		isClosedDurableIssuanceRecord,
8		isValidDurableAuthorSequence,
9	} from "./contract.js";
10	import type { DurableIssuanceError, DurableIssueScope, DurableLineage } from "./types.js";
11	
12	const HEX_DIGEST = /^[0-9a-f]{64}$/u;
13	
14	export interface DurableIssuancePruningState {
15		readonly lineage: DurableLineage;
16		readonly prunedThroughAuthorSequence: number | null;
17		readonly scope: DurableIssueScope;
18	}
19	
20	export interface DurableIssuancePruningInput {
21		readonly closedEpoch: number;
22		readonly commitQcRef: Readonly<{ readonly byteLength: number; readonly digest: string }>;
23		readonly expectedLineage: DurableLineage;
24		readonly expectedPrunedThroughAuthorSequence: number | null;
25		readonly scope: DurableIssueScope;
26		readonly snapshotManifestDigest: string;
27		readonly throughAuthorSequence: number;
28	}
