45	/** Exact non-poisoning evidence that a caller-known ordinal was already pruned. */
46	export class DurableIssuanceRecordPrunedError extends Error implements DurableIssuanceError {
47		readonly authorSequence: number;
48		readonly code = "ISSUANCE_RECORD_PRUNED" as const;
49		readonly scope: DurableIssueScope;
50	
51		/**
52		 * Creates caller-known evidence for an ordinal already removed by pruning.
53		 * @param scope - Caller-known issuance scope.
54		 * @param authorSequence - Caller-known pruned ordinal.
55		 */
56		constructor(scope: DurableIssueScope, authorSequence: number) {
57			super("durable issuance record was pruned");
58			Object.defineProperty(this, "name", { configurable: true, value: "DurableIssuanceError" });
59			this.authorSequence = authorSequence;
60			this.scope = Object.freeze(copyDurableIssueScope(scope));
61		}
62	}
63	
64	function invalid(message: string): DurableIssuanceInvalidArgumentError {
65		return new DurableIssuanceInvalidArgumentError(message);
66	}
67	
68	function copyLineage(value: unknown): DurableLineage {
69		if (
70			!isClosedDurableIssuanceRecord(value, ["exhausted", "next"]) ||
71			typeof value.exhausted !== "boolean" ||
72			!isValidDurableAuthorSequence(value.next) ||
73			(value.exhausted && value.next !== Number.MAX_SAFE_INTEGER)
74		) {
75			throw invalid("expectedLineage must be an exact safe lineage record");
76		}
77		return { exhausted: value.exhausted, next: value.next };
78	}
79	
80	function copyWatermark(value: unknown): number | null {
81		if (value === null) return null;
82		if (!isValidDurableAuthorSequence(value)) throw invalid("pruning watermark must be null or a safe ordinal");
83		return value;
84	}
85	
86	/**
87	 * Validates and detaches one closed pruning request.
88	 * @param value - Untrusted request value.
89	 * @returns A detached validated pruning request.
90	 */
91	export function captureDurableIssuancePruningInput(value: unknown): DurableIssuancePruningInput {
92		try {
93			if (
94				!isClosedDurableIssuanceRecord(value, [
95					"closedEpoch",
96					"commitQcRef",
97					"expectedLineage",
98					"expectedPrunedThroughAuthorSequence",
99					"scope",
100					"snapshotManifestDigest",
101					"throughAuthorSequence",
102				]) ||
103				!isValidDurableAuthorSequence(value.closedEpoch) ||
104				!isValidDurableAuthorSequence(value.throughAuthorSequence) ||
105				!isClosedDurableIssuanceRecord(value.commitQcRef, ["byteLength", "digest"]) ||
106				!Number.isSafeInteger(value.commitQcRef.byteLength) ||
107				Number(value.commitQcRef.byteLength) < 1 ||
108				typeof value.commitQcRef.digest !== "string" ||
109				!HEX_DIGEST.test(value.commitQcRef.digest) ||
110				typeof value.snapshotManifestDigest !== "string" ||
111				!HEX_DIGEST.test(value.snapshotManifestDigest)
112			) {
113				throw invalid("pruning input must be one exact validated record");
114			}
115			assertDurableIssueScope(value.scope);
116			return {
117				closedEpoch: value.closedEpoch,
118				commitQcRef: { byteLength: Number(value.commitQcRef.byteLength), digest: value.commitQcRef.digest },
119				expectedLineage: copyLineage(value.expectedLineage),
120				expectedPrunedThroughAuthorSequence: copyWatermark(value.expectedPrunedThroughAuthorSequence),
121				scope: copyDurableIssueScope(value.scope),
122				snapshotManifestDigest: value.snapshotManifestDigest,
123				throughAuthorSequence: value.throughAuthorSequence,
124			};
125		} catch (error) {
126			if (error instanceof DurableIssuanceInvalidArgumentError) throw error;
127			throw invalid("pruning input could not be inspected as a closed record");
128		}
129	}
