131	/**
132	 * Compares two lineage CAS values.
133	 * @param left - First lineage value.
134	 * @param right - Second lineage value.
135	 * @returns Whether both lineage fields are equal.
136	 */
137	export function durableIssuanceLineagesEqual(left: DurableLineage, right: DurableLineage): boolean {
138		return left.exhausted === right.exhausted && left.next === right.next;
139	}
140	
141	/**
142	 * Tests whether a lineage has consumed an ordinal.
143	 * @param lineage - Observed durable lineage.
144	 * @param authorSequence - Ordinal to classify.
145	 * @returns Whether the lineage has consumed the ordinal.
146	 */
147	export function durableIssuanceLineageConsumed(lineage: DurableLineage, authorSequence: number): boolean {
148		return lineage.next > authorSequence || (lineage.exhausted && lineage.next === authorSequence);
149	}
150	
151	/**
152	 * Tests the explicit inclusive pruning-watermark relation.
153	 * @param watermark - Inclusive watermark or no pruning state.
154	 * @param authorSequence - Ordinal to classify.
155	 * @returns Whether the ordinal is at or below a real watermark.
156	 */
157	export function durableIssuanceAddressIsPruned(watermark: number | null, authorSequence: number): boolean {
158		return watermark !== null && authorSequence <= watermark;
159	}
160	
161	/**
162	 * Decodes only the closed v3 vertex fields needed by the issuance owner.
163	 * @param canonicalPreimageBytes - Canonical preimage bytes to decode.
164	 * @param scope - Expected issuance scope.
165	 * @param authorSequence - Expected issuance ordinal.
166	 * @returns The validated epoch or `undefined` for any mismatch.
167	 */
168	export function decodeDurableIssuancePreimage(
169		canonicalPreimageBytes: Uint8Array,
170		scope: DurableIssueScope,
171		authorSequence: number
172	): Readonly<{ readonly epoch: number }> | undefined {
173		try {
174			const decoded: unknown = decodeCanonical(canonicalPreimageBytes);
175			if (typeof decoded !== "object" || decoded === null || Array.isArray(decoded)) return undefined;
