162	function claimCreatorCloseRegistration(plane: V3PlaneHandle): V3CreatorCloseRegistration | undefined {
163		const registration = creatorCloseRegistrationResolver?.(plane);
164		return plainRecord(registration) ? (registration as unknown as V3CreatorCloseRegistration) : undefined;
165	}
166	
167	function verifiedCreatorTrustRecord(
168		registration: V3CreatorCloseRegistration,
169		exactCanonicalTrustStateRecordBytes: Uint8Array
170	): Readonly<Record<string, unknown>> | undefined {
171		try {
172			const record = decodeCanonical(exactCanonicalTrustStateRecordBytes);
173			if (!plainRecord(record) || !(record.exactCanonicalSignerSetBytes instanceof Uint8Array)) return undefined;
174			const signerSet = decodeCanonical(record.exactCanonicalSignerSetBytes);
175			return record.currentAnchorDigest === registration.currentTrust.currentAnchorDigest &&
176				record.currentEpoch === registration.currentTrust.currentEpoch &&
177				record.genesisAnchorDigest === registration.currentTrust.genesisAnchorDigest &&
178				record.objectId === registration.currentTrust.objectId &&
179				record.profileId === registration.currentTrust.profileId &&
180				record.profileId === "creator-trusted-v1" &&
181				record.quorum === 1 &&
182				Array.isArray(signerSet) &&
183				signerSet.length === 1
184				? record
185				: undefined;
186		} catch {
187			return undefined;
188		}
189	}
190	
191	function copiedRef(ref: GenerationRef): GenerationRef {
192		return Object.freeze({ byteLength: ref.byteLength, digest: ref.digest });
193	}
194	
195	function compareRef(left: GenerationRef, right: GenerationRef): number {
196		return left.digest < right.digest ? -1 : left.digest > right.digest ? 1 : 0;
197	}
198	
199	function plainRecord(value: unknown): value is Readonly<Record<string, unknown>> {
200		return value !== null && typeof value === "object" && !Array.isArray(value);
201	}
202	
203	function successfulValue<T>(value: unknown): T | undefined {
204		if (!plainRecord(value) || value.ok !== true || !Object.hasOwn(value, "value")) return undefined;
205		return value.value as T;
206	}
207	
208	function successfulUndefined(value: unknown): boolean {
209		return plainRecord(value) && value.ok === true && Object.hasOwn(value, "value") && value.value === undefined;
210	}
211	
212	function refFor(bytes: Uint8Array): GenerationRef {
213		const digest = digestBlob(bytes);
214		if (!digest.ok) throw new TypeError("creator close blob digest failed");
215		return Object.freeze({ byteLength: bytes.byteLength, digest: digest.value });
216	}
217	
218	function sameRef(left: GenerationRef, right: GenerationRef): boolean {
219		return left.byteLength === right.byteLength && left.digest === right.digest;
220	}
221	
222	function hex(bytes: Uint8Array): string {
223		return Array.from(bytes, (byte) => byte.toString(16).padStart(2, "0")).join("");
224	}
225	
226	function sameHead(left: PresentHead, right: PresentHead): boolean {
227		return (
228			left.closureDigest === right.closureDigest &&
229			left.generationId === right.generationId &&
230			left.objectId === right.objectId &&
231			left.revision === right.revision
232		);
233	}
234	
235	function generationId(): GenerationId {
236		const bytes = new Uint8Array(32);
237		crypto.getRandomValues(bytes);
238		const parsed = parseGenerationId(Array.from(bytes, (byte) => byte.toString(16).padStart(2, "0")).join(""));
239		if (!parsed.ok) throw new TypeError("creator close generation identity failed");
240		return parsed.value;
241	}
