243	async function inspectHead(
244		store: AheDurableStore,
245		objectId: Parameters<AheDurableStore["recoverActiveGeneration"]>[0]
246	): Promise<
247		Readonly<{
248			candidates: readonly Readonly<{ bytes: Uint8Array; ref: GenerationRef }>[];
249			head: PresentHead;
250			references: readonly GenerationRef[];
251			trustRef: GenerationRef;
252		}>
253	> {
254		const recovered = successfulValue<Readonly<Record<string, unknown>>>(await store.recoverActiveGeneration(objectId));
255		if (recovered?.kind !== "active" || !plainRecord(recovered.head) || !Array.isArray(recovered.references)) {
256			throw new TypeError("creator close active generation is unavailable");
257		}
258		const references = Object.freeze((recovered.references as GenerationRef[]).map(copiedRef));
259		const candidates: Array<Readonly<{ bytes: Uint8Array; ref: GenerationRef }>> = [];
260		for (const ref of references) {
261			if (ref.byteLength > SCANNABLE_BYTES) continue;
262			const bytes = successfulValue<Uint8Array | null>(await store.getBlob(ref.digest));
263			if (!(bytes instanceof Uint8Array)) throw new TypeError("creator close generation blob is unavailable");
264			candidates.push(Object.freeze({ bytes: Uint8Array.from(bytes), ref }));
265		}
266		const inspected = inspectTrustClosure({ candidates, closure: references });
267		if (!inspected.ok) throw new TypeError(`creator close trust scan failed: ${inspected.reason}`);
268		return Object.freeze({
269			candidates: Object.freeze(candidates),
270			head: Object.freeze({ ...(recovered.head as PresentHead) }),
271			references,
272			trustRef: copiedRef(inspected.trustRef),
273		});
274	}
