276	async function persistSnapshot(
277		store: SnapshotQuarantineStore<SnapshotVerificationReceipt>,
278		input: Readonly<{
279			aclDigest: string;
280			anchor: string;
281			epoch: number;
282			exactCanonicalPayloadBytes: Uint8Array;
283			objectId: string;
284			stateDigest: string;
285		}>
286	): Promise<
287		Readonly<{
288			declaration: SnapshotQuarantineDeclaration;
289			exactCanonicalManifestBytes: Uint8Array;
290			manifestDigest: string;
291		}>
292	> {
293		const encoded = encodeSnapshotTransfer({ ...input, profile: PROFILE, schemaVersion: 1 });
294		const decoded = decodeSnapshotManifest({
295			exactCanonicalManifestBytes: encoded.exactCanonicalManifestBytes,
296			expectedManifestDigest: encoded.manifestDigest,
297			profile: PROFILE,
298		});
299		const scopeKey = Object.freeze({
300			anchor: input.anchor,
301			epoch: input.epoch,
302			manifestDigest: encoded.manifestDigest,
303			objectId: input.objectId,
304		});
305		const scope = await store.openScope({
306			chunks: decoded.chunks,
307			exactCanonicalManifestBytes: encoded.exactCanonicalManifestBytes,
308			scope: scopeKey,
309			totalBytes: decoded.chunks.reduce((total, chunk) => total + chunk.byteLength, 0),
310		});
311		try {
312			const verified = verifySnapshotStreamWithReceipt({
313				exactCanonicalManifestBytes: encoded.exactCanonicalManifestBytes,
314				expectedManifestDigest: encoded.manifestDigest,
315				expectedScope: scopeKey,
316				profile: PROFILE,
317				quarantine: scope.verificationQuarantine,
318				source: Object.freeze({
319					read: (descriptor: Readonly<{ readonly index: number }>) =>
320						Promise.resolve(
321							encoded.chunks[descriptor.index] === undefined ? undefined : encoded.chunks[descriptor.index]
322						),
323				}),
324			});
325			await verified.completion;
326			await scope.complete(await verified.receipt);
327			return Object.freeze({
328				declaration: Object.freeze({
329					chunks: Object.freeze(decoded.chunks.map((chunk) => Object.freeze({ ...chunk }))),
330					exactCanonicalManifestBytes: Uint8Array.from(encoded.exactCanonicalManifestBytes),
331					scope: scopeKey,
332					totalBytes: decoded.chunks.reduce((total, chunk) => total + chunk.byteLength, 0),
333				}),
334				exactCanonicalManifestBytes: Uint8Array.from(encoded.exactCanonicalManifestBytes),
335				manifestDigest: encoded.manifestDigest,
336			});
337		} finally {
338			await scope.release();
339		}
340	}
