342	async function stageCombinedGeneration(
343		store: AheDurableStore,
344		current: Awaited<ReturnType<typeof inspectHead>>,
345		newBlobs: readonly Readonly<{ bytes: Uint8Array; ref: GenerationRef }>[],
346		proposed: readonly GenerationRef[]
347	): Promise<PresentHead> {
348		const selectedGenerationId = generationId();
349		const closureDigest = digestClosure(proposed);
350		if (!closureDigest.ok) throw new TypeError("creator close closure digest failed");
351		const begun = successfulValue<Readonly<{ readonly closureDigest: string }>>(
352			await store.beginGeneration({
353				baseExpectedHead: current.head,
354				closure: proposed,
355				generationId: selectedGenerationId,
356				objectId: current.head.objectId,
357			})
358		);
359		if (begun?.closureDigest !== closureDigest.value) throw new TypeError("creator close generation staging failed");
360		for (const blob of newBlobs) {
361			const cached = successfulValue<Readonly<{ readonly inserted: boolean }>>(
362				await store.putCachedBlob({
363					bytes: blob.bytes,
364					digest: blob.ref.digest,
365					generationId: selectedGenerationId,
366					objectId: current.head.objectId,
367				})
368			);
369			if (cached === undefined) throw new TypeError("creator close blob staging failed");
370		}
371		for (const ref of proposed) {
372			const promoted = await store.promoteReference({
373				digest: ref.digest,
374				generationId: selectedGenerationId,
375				objectId: current.head.objectId,
376			});
377			if (!successfulUndefined(promoted)) throw new TypeError("creator close reference promotion failed");
378		}
379		const completed = successfulValue<Readonly<{ readonly closureDigest: string }>>(
380			await store.completeGeneration({ generationId: selectedGenerationId, objectId: current.head.objectId })
381		);
382		if (completed?.closureDigest !== closureDigest.value)
383			throw new TypeError("creator close generation completion failed");
384		let swapped: PresentHead | undefined;
385		try {
386			const result = successfulValue<Readonly<{ readonly head: PresentHead }>>(
387				await store.swapHead({
388					expectedHead: current.head,
389					generationId: selectedGenerationId,
390					objectId: current.head.objectId,
391				})
392			);
393			swapped = result?.head;
394		} catch {
395			// Reopen below decides whether an ambiguous write committed.
396		}
397		const reopened = await inspectHead(store, current.head.objectId);
398		const expected = Object.freeze({
399			closureDigest: closureDigest.value,
400			generationId: selectedGenerationId,
401			kind: "present" as const,
402			objectId: current.head.objectId,
403			revision: current.head.revision + 1,
404		}) as PresentHead;
405		if (!sameHead(reopened.head, expected) || (swapped !== undefined && !sameHead(swapped, expected))) {
406			throw new TypeError("creator close head swap lost or remained ambiguous");
407		}
408		return reopened.head;
409	}
