411	/**
412	 * Binds one creator-only close authority to a genuine active v3 plane.
413	 * @param input - Opaque signer, durable actor stores, quarantine and receiver-bound plane.
414	 * @returns The sole live close handle or a closed authority failure.
415	 */
416	export async function bindCreatorLiveClose(
417		input: BindCreatorLiveCloseInput
418	): Promise<Readonly<{ handle: CreatorLiveCloseHandle; ok: true } | { ok: false; reason: string }>> {
419		try {
420			const existing = bindings.get(input.plane);
421			if (existing !== undefined) return Object.freeze({ handle: existing, ok: true as const });
422			const registration = claimCreatorCloseRegistration(input.plane);
423			if (registration === undefined) return Object.freeze({ ok: false as const, reason: "CREATOR_CLOSE_UNAVAILABLE" });
424			const epoch = registration.currentTrust.currentEpoch;
425			if (!Number.isSafeInteger(epoch) || epoch < 0 || epoch === Number.MAX_SAFE_INTEGER) {
426				return Object.freeze({ ok: false as const, reason: "CREATOR_CLOSE_UNAVAILABLE" });
427			}
428			const successorEpoch = epoch + 1;
429			const boundHead = await inspectHead(registration.store, registration.objectId);
430			const boundTrustCandidate = boundHead.candidates.find(({ ref }) => sameRef(ref, boundHead.trustRef));
431			if (
432				boundTrustCandidate === undefined ||
433				verifiedCreatorTrustRecord(registration, boundTrustCandidate.bytes) === undefined
434			) {
435				return Object.freeze({ ok: false as const, reason: "CREATOR_TRUST_UNAVAILABLE" });
436			}
437			const opened = await createCreatorSealActor({
438				currentTrust: registration.currentTrust,
439				evidenceStore: input.evidenceStore,
440				onObservation: input.onObservation,
441				signer: input.signer,
442				storageIncarnation: input.storageIncarnation,
443				voteStore: input.voteStore,
444			});
445			if (!opened.ok) return Object.freeze({ ok: false as const, reason: opened.reason });
446			if (opened.actor.status().terminal) {
447				await opened.actor.stop();
448				return Object.freeze({ ok: false as const, reason: "CREATOR_CONTINUITY_TERMINAL" });
449			}
450			const actor = opened.actor as CreatorActor;
451			let lifecycle: CreatorLiveCloseStatus["lifecycle"] = "active";
452			let closeTask: Promise<CreatorLiveCloseResult> | undefined;
453			let stagedSnapshot:
454				| Extract<Awaited<ReturnType<V3CreatorCloseRegistration["stageSnapshot"]>>, { readonly ok: true }>
455				| undefined;
456			let capturedGraph: Exclude<ReturnType<V3CreatorCloseRegistration["captureCloseGraph"]>, undefined> | undefined;
457			let persistedSnapshot: Awaited<ReturnType<typeof persistSnapshot>> | undefined;
458			let derivedCommitment: Awaited<ReturnType<typeof deriveCloseSetHistoryCommitment>> | undefined;
459			let durableReplay: Readonly<{ verify(): Promise<boolean> }> | undefined;
460			const trust = Object.freeze({
461				byzantineFaultTolerant: false as const,
462				kind: "creator-certified" as const,
463				quorum: 1 as const,
464				signerCount: 1 as const,
465				text: "Creator-certified; one of one; not Byzantine-fault-tolerant." as const,
466			});
467			const handle: CreatorLiveCloseHandle = Object.freeze({
468				close: (): Promise<CreatorLiveCloseResult> => {
469					if (
470						closeTask !== undefined ||
471						lifecycle === "successor-pending-adoption" ||
472						lifecycle === "successor-adopted" ||
473						actor.status().terminal
474					) {
475						return Promise.reject(new TypeError("creator close authority is unavailable"));
476					}
477					closeTask = (async (): Promise<CreatorLiveCloseResult> => {
478						if (stagedSnapshot === undefined) {
479							const snapshot = await registration.stageSnapshot();
480							if (!snapshot.ok) {
481								registration.abortSnapshotStage();
482								throw new TypeError(`creator snapshot export failed: ${snapshot.kind}`);
483							}
484							stagedSnapshot = snapshot;
485						}
486						lifecycle = "sealed";
487						capturedGraph ??= registration.captureCloseGraph();
488						if (capturedGraph === undefined) throw new TypeError("creator close graph capture failed");
489						const snapshot = stagedSnapshot;
490						const graph = capturedGraph;
491						const payload = decodeCanonical(snapshot.exactCanonicalPayloadBytes);
492						const anchor = decodeCanonical(registration.exactCanonicalAnchorPreimageBytes);
493						if (!plainRecord(payload) || !plainRecord(anchor))
494							throw new TypeError("creator close snapshot identity failed");
495						const acl = payload.acl;
496						const stateDigest = snapshot.applicationStateDigest;
497						const archiveIndexRoot = anchor.archiveIndexRoot;
498						if (acl === undefined || typeof stateDigest !== "string" || typeof archiveIndexRoot !== "string") {
499							throw new TypeError("creator close snapshot identity failed");
500						}
501						const aclDigest = hex(hashDomain("ts-drp/latched-acl/v3", encodeCanonical(acl)));
502						persistedSnapshot ??= await persistSnapshot(input.snapshotStore, {
503							aclDigest,
504							anchor: registration.currentTrust.currentAnchorDigest,
505							epoch: registration.currentTrust.currentEpoch,
506							exactCanonicalPayloadBytes: snapshot.exactCanonicalPayloadBytes,
507							objectId: registration.objectId,
508							stateDigest,
509						});
510						derivedCommitment ??= await deriveCloseSetHistoryCommitment({
511							authenticatedCanonicalPreimageByteLengths: graph.charges,
512							exactCanonicalEpochAnchorPreimageBytes: registration.exactCanonicalAnchorPreimageBytes,
513							frontier: graph.frontier,
514							maxEpochBytes: registration.maxEpochBytes,
515							maxEpochVertices: registration.maxEpochVertices,
516							previousHistorySnapshot: registration.previousHistorySnapshot,
517							vertices: graph.vertices,
518						});
519						const commitment = derivedCommitment;
520						durableReplay ??= await registration.sealDurableReplay();
521						if (durableReplay === undefined) throw new TypeError("creator close durable replay seal failed");
522						const current = await inspectHead(registration.store, registration.objectId);
523						const currentTrustCandidate = current.candidates.find(({ ref }) => sameRef(ref, current.trustRef));
524						if (currentTrustCandidate === undefined) throw new TypeError("creator current trust bytes are unavailable");
525						const decodedTrust = verifiedCreatorTrustRecord(registration, currentTrustCandidate.bytes);
526						if (decodedTrust === undefined || !(decodedTrust.exactCanonicalSignerSetBytes instanceof Uint8Array)) {
527							throw new TypeError("creator signer set is unavailable");
528						}
529						const closeInput = Object.freeze({
530							aclDigest,
531							archiveIndexRoot,
532							blueprintDigest: anchor.blueprintDigest,
533							closeReason: "creator-requested",
534							closeSetCount: commitment.closeSetCount,
535							closeSetRoot: commitment.closeSetRoot,
536							currentTrust: registration.currentTrust,
537							exactCanonicalAvailabilityPolicyBytes: Uint8Array.from(input.exactCanonicalAvailabilityPolicyBytes),
538							exactCanonicalNextSignerSetBytes: Uint8Array.from(decodedTrust.exactCanonicalSignerSetBytes),
539							exactCanonicalParametersBytes: Uint8Array.from(registration.exactCanonicalParametersBytes),
540							exactCanonicalSnapshotManifestBytes: persistedSnapshot.exactCanonicalManifestBytes,
541							historyRoot: commitment.historyRoot,
542							historySize: commitment.historySize,
543							snapshotManifestDigest: persistedSnapshot.manifestDigest,
544							stateDigest,
545						});
546						const prepared = prepareCreatorClose(closeInput);
547						if (!prepared.ok) throw new TypeError(`creator close preparation failed: ${prepared.reason}`);
548						const finalized = await actor.close({ closeInput });
549						if (
550							finalized.ok !== true ||
551							!(finalized.exactCanonicalCommitQcBytes instanceof Uint8Array) ||
552							!(finalized.exactCanonicalTrustStateRecordBytes instanceof Uint8Array)
553						)
554							throw new TypeError(`creator close actor failed: ${String(finalized.reason)}`);
555						const successor = openCreatorSuccessorTrust({
556							currentTrust: registration.currentTrust,
557							exactCanonicalCommitQcBytes: finalized.exactCanonicalCommitQcBytes,
558							exactCanonicalCutValueBytes: prepared.exactCanonicalCutValueBytes,
559							exactCanonicalTrustStateRecordBytes: finalized.exactCanonicalTrustStateRecordBytes,
560						});
561						if (!successor.ok) throw new TypeError(`creator successor reopen failed: ${successor.reason}`);
562						if (
563							successor.trust.currentEpoch !== successorEpoch ||
564							successor.trust.objectId !== registration.currentTrust.objectId ||
565							successor.trust.genesisAnchorDigest !== registration.currentTrust.genesisAnchorDigest
566						) {
567							throw new TypeError("creator successor epoch identity failed");
568						}
569						const successorTrustRef = refFor(finalized.exactCanonicalTrustStateRecordBytes);
570						const cutValueRef = refFor(prepared.exactCanonicalCutValueBytes);
571						const commitQcRef = refFor(finalized.exactCanonicalCommitQcBytes);
572						const proposed = Object.freeze(
573							[
574								...current.references.filter(({ digest }) => digest !== current.trustRef.digest),
575								successorTrustRef,
576								cutValueRef,
577								commitQcRef,
578							].sort(compareRef)
579						);
580						const proposedCandidates = [
581							...current.candidates.filter(({ ref }) => ref.digest !== current.trustRef.digest),
582							{ bytes: finalized.exactCanonicalTrustStateRecordBytes, ref: successorTrustRef },
583							{ bytes: prepared.exactCanonicalCutValueBytes, ref: cutValueRef },
584							{ bytes: finalized.exactCanonicalCommitQcBytes, ref: commitQcRef },
585						].filter(({ ref }) => ref.byteLength <= SCANNABLE_BYTES);
586						const advance = inspectCreatorTransitionAdvance({
587							current: { candidates: current.candidates, closure: current.references },
588							mode: "stage",
589							proofRefs: [cutValueRef, commitQcRef],
590							proposed: { candidates: proposedCandidates, closure: proposed },
591						});
592						if (!advance.ok) throw new TypeError(`creator trust advance failed: ${advance.reason}`);
593						const acceptedProposed = advance.proposed.closure;
594						const proposedHead = await stageCombinedGeneration(
595							registration.store,
596							current,
597							[
598								{ bytes: finalized.exactCanonicalTrustStateRecordBytes, ref: successorTrustRef },
599								{ bytes: prepared.exactCanonicalCutValueBytes, ref: cutValueRef },
600								{ bytes: finalized.exactCanonicalCommitQcBytes, ref: commitQcRef },
601							],
602							acceptedProposed
603						);
