168				retiringCutRecord.epoch !== identity.currentEpoch - 1 ||
169				retiringQcRecord?.kind !== "drp-seal-qc" ||
170				retiringQcRecord.objectId !== identity.objectId ||
171				retiringQcRecord.epoch !== identity.currentEpoch - 1 ||
172				retiringQcRecord.phase !== "commit"
173			) {
174				return rejected("RETIRING_PROOF_REFS_INVALID");
175			}
176			if (
177				retiringAcl === undefined ||
178				retiringAclRecord?.kind !== "drp-v3-latched-acl" ||
179				retiringAclRecord.objectId !== identity.objectId ||
180				retiringAclRecord.epoch !== identity.currentEpoch - 1
